package com.clavis.reader;
import android.app.*;
import android.os.*;
import android.content.*;
import android.net.*;
import android.webkit.*;
import android.widget.*;
import android.view.*;
public final class AudiobookBrowserActivity extends MainActivity {
 private boolean ebook;private String homeUrl;private WebView web;private TextView notice;private ProgressBar progress;
 @Override public void onCreate(Bundle state){super.onCreate(state);ebook=getIntent().getBooleanExtra("ebook",false);homeUrl=BrowserSettings.home(this,ebook);screen="Reader";shell(ebook?"Browse ebooks":"Browse audiobooks");screen="Browser";bar.getChildAt(0).setOnClickListener(v->onBackPressed());bar.getChildAt(2).setContentDescription(ebook?"Find on page":"Search audiobook website");bar.getChildAt(2).setOnClickListener(v->searchSite());bar.addView(UiStyle.icon(this,R.drawable.ic_toolbar_more,"Browser menu",()->new AppDialog.Builder(this).setItems(new String[]{"Downloads",ebook?"Website settings":"Paste magnet link","Website home","Reload"},(d,n)->{if(n==0)startActivity(new Intent(this,DownloadsActivity.class));else if(n==1&&ebook){BrowserSettings.show(this,true);}else if(n==1){startActivity(new Intent(this,DownloadsActivity.class).putExtra("paste",true));}else if(n==2)web.loadUrl(homeUrl);else web.reload();}).show(),34));root.removeViewAt(1);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);AppTheme.tintProgress(progress);progress.setMax(100);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));notice=text(Uri.parse(homeUrl).getHost(),11,MUTED,false);notice.setPadding(dp(12),dp(5),dp(12),dp(5));root.addView(notice);bar.addView(UiStyle.icon(this,R.drawable.ic_close_browser,"Close browser",this::finish,34));web=new WebView(this);web.setBackgroundColor(AppTheme.background);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setSupportMultipleWindows(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return navigate(request.getUrl().toString());}@Override public void onPageFinished(WebView view,String url){notice.setText(Uri.parse(url).getHost());}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())notice.setText("Page unavailable. Use the menu to reload.");}});web.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView view,int value){progress.setProgress(value);progress.setVisibility(value==100?View.GONE:View.VISIBLE);}});web.setDownloadListener((url,agent,disposition,mime,size)->{if(url.startsWith("magnet:"))DownloadsActivity.offer(this,url);else if(ebook)EbookDownloads.offer(this,url,agent,disposition,mime,web.getUrl());else new AppDialog.Builder(this).setTitle("Download link").setMessage("Use the book's magnet link to start an audiobook transfer. You can also paste a magnet link in Downloads.").setPositiveButton("OK",null).show();});if(state==null||web.restoreState(state)==null)web.loadUrl(homeUrl);
 }
 private boolean navigate(String url){Uri uri=Uri.parse(url);if("magnet".equalsIgnoreCase(uri.getScheme())){DownloadsActivity.offer(this,url);return true;}String host=uri.getHost();if("https".equalsIgnoreCase(uri.getScheme())&&host!=null&&(ebook||sameWebsite(host)))return false;notice.setText("External link blocked. Use Website settings to change the browsing website.");return true;}
 private boolean sameWebsite(String host){String expected=Uri.parse(homeUrl).getHost();if(expected==null)return false;String bare=expected.startsWith("www.")?expected.substring(4):expected;return host.equalsIgnoreCase(bare)||host.toLowerCase(java.util.Locale.ROOT).endsWith("."+bare.toLowerCase(java.util.Locale.ROOT));}
 private void searchSite(){if(ebook){EditText query=new EditText(this);query.setTextColor(INK);query.setSingleLine();new AppDialog.Builder(this).setTitle("Find on page").setView(query).setPositiveButton("Find",(d,n)->web.findAllAsync(query.getText().toString())).setNegativeButton("Cancel",null).show();return;}EditText input=new EditText(this);input.setSingleLine();input.setHint("Title, author or narrator");input.setTextColor(INK);new AppDialog.Builder(this).setTitle("Search audiobook website").setView(input).setPositiveButton("Search",(d,n)->web.loadUrl(Uri.parse(homeUrl).buildUpon().clearQuery().appendQueryParameter("s",input.getText().toString()).build().toString())).setNegativeButton("Cancel",null).show();}
 @Override protected void onResume(){super.onResume();if(web!=null){String updated=BrowserSettings.home(this,ebook);if(!updated.equals(homeUrl)){homeUrl=updated;web.loadUrl(homeUrl);}}}
 @Override protected void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else finish();}
 @Override protected void onDestroy(){if(web!=null){web.stopLoading();web.destroy();}super.onDestroy();}
}
